33:                     if (!pending_q) fault_q <= 1'b1;
34:                     pending_q <= 1'b0;
35:                     eligible_q <= 1'b0;
36:                 end
37:                 2'b11: begin
38:                     // Replace a completed sole job; an immediately completed
39:                     // job with no predecessor needs no read permission.
40:                     pending_q <= pending_q;
41:                     eligible_q <= pending_q && eligible;
42:                 end
43:                 default: ;
44:             endcase
45:         end
46:     end
